 const both=sample(result,'block_entity_selector_both');server(both.value);assert.equal(both.body.perspective,'both');assert.deepEqual(both.body.selector.blocks,[fixture.b]);assert.deepEqual(both.value.server.blockEntities.map(row=>row.key),[key(fixture.b)]);assert(both.value.client&&!Object.hasOwn(both.value.client,'blockEntities'));
 const denied=sample(result,'block_entity_selector_client_rejected');assert.equal(denied.body.perspective,'client_known');assert.equal(denied.httpStatus,400);assert.equal(denied.denied.error,'UNSUPPORTED_DEEP_SELECTOR');assert(!Object.hasOwn(denied.denied,'client')&&!Object.hasOwn(denied.denied,'server'));
